function bookings_validate_insert(array $data): array
{
    $errors = [];
    if (!array_key_exists('user_id', $data) || $data['user_id'] === null || $data['user_id'] === '') {
        $errors['user_id'] = 'required';
    }
    if (isset($data['user_id']) && $data['user_id'] !== null && !ctype_digit((string)$data['user_id'])) {
        $errors['user_id'] = 'must be an integer';
    }
    if (!array_key_exists('room_id', $data) || $data['room_id'] === null || $data['room_id'] === '') {
        $errors['room_id'] = 'required';
    }
    if (isset($data['room_id']) && $data['room_id'] !== null && !ctype_digit((string)$data['room_id'])) {
        $errors['room_id'] = 'must be an integer';
    }
    if (!array_key_exists('check_in', $data) || $data['check_in'] === null || $data['check_in'] === '') {
        $errors['check_in'] = 'required';
    }
    if (!array_key_exists('check_out', $data) || $data['check_out'] === null || $data['check_out'] === '') {
        $errors['check_out'] = 'required';
    }
    if (isset($data['status']) && !in_array($data['status'], ['pending','confirmed','cancelled'], true)) {
        $errors['status'] = 'must be one of: 'pending','confirmed','cancelled'';
    }
    return $errors;
}

