function bookings_handle(Request $req): void
{
    $db = DB::get();
    $id = $req->id();

    // GET /bookings/{id}/payments[?filters]
    if ($req->method === 'GET' && $id !== null && $req->nested() === 'payments') {
        $filters = array_diff_key($req->query, ['page' => 1, 'per_page' => 1]);
        $page    = max(1, (int)($req->query['page'] ?? 1));
        $perPage = min(100, (int)($req->query['per_page'] ?? 20));
        $offset  = ($page - 1) * $perPage;
        $where   = ['booking_id = ?'];
        $params  = [$id];
        foreach ($filters as $col => $val) {
            $where[]  = "`{$col}` = ?";
            $params[] = $val;
        }
        $whereStr = implode(' AND ', $where);
        $count = DB::get()->prepare("SELECT COUNT(*) FROM `payments` WHERE {$whereStr}");
        $count->execute($params);
        $stmt = DB::get()->prepare("SELECT * FROM `payments` WHERE {$whereStr} LIMIT ? OFFSET ?");
        $stmt->execute([...$params, $perPage, $offset]);
        Response::ok([
            'data' => $stmt->fetchAll(),
            'meta' => ['page' => $page, 'per_page' => $perPage, 'total' => (int)$count->fetchColumn()],
        ]);
    }

    // GET /bookings/{id}  — single record
    if ($req->method === 'GET' && $id !== null && $req->nested() === null) {
        $stmt = $db->prepare("SELECT * FROM `bookings` WHERE `id` = ? LIMIT 1");
        $stmt->execute([$id]);
        $row = $stmt->fetch();
        if (!$row) Response::notFound('Bookings not found');
        Response::ok($row);
    }

    // GET /bookings  — list (filters + pagination)
    if ($req->method === 'GET' && $id === null) {
        $filters = array_diff_key($req->query, ['page' => 1, 'per_page' => 1]);
        $page    = max(1, (int)($req->query['page']     ?? 1));
        $perPage = min(100, (int)($req->query['per_page'] ?? 20));
        $offset  = ($page - 1) * $perPage;

        $where  = ['1=1'];
        $params = [];
        foreach ($filters as $col => $val) {
            $where[]  = "`{$col}` = ?";
            $params[] = $val;
        }
        $whereStr = implode(' AND ', $where);

        $count = $db->prepare("SELECT COUNT(*) FROM `bookings` WHERE {$whereStr}");
        $count->execute($params);

        $stmt = $db->prepare("SELECT * FROM `bookings` WHERE {$whereStr} LIMIT ? OFFSET ?");
        $stmt->execute([...$params, $perPage, $offset]);

        Response::ok([
            'data' => $stmt->fetchAll(),
            'meta' => [
                'page'     => $page,
                'per_page' => $perPage,
                'total'    => (int)$count->fetchColumn(),
            ],
        ]);
    }

    // POST /bookings  — create
    if ($req->method === 'POST' && $id === null) {
        $data   = $req->body;
        $errors = bookings_validate_insert($data);
        if ($errors) Response::unprocessable($errors);

        $values = array_map(fn($c) => $data[$c] ?? null, array (
  0 => 'user_id',
  1 => 'room_id',
  2 => 'check_in',
  3 => 'check_out',
  4 => 'status',
));
        $stmt   = $db->prepare("INSERT INTO `bookings` (`user_id`, `room_id`, `check_in`, `check_out`, `status`) VALUES (?, ?, ?, ?, ?)");
        $stmt->execute($values);

        $stmt = $db->prepare("SELECT * FROM `bookings` WHERE `id` = ? LIMIT 1");
        $stmt->execute([$db->lastInsertId()]);
        Response::created($stmt->fetch());
    }

    // PUT /bookings/{id}  — update
    if ($req->method === 'PUT' && $id !== null) {
        $stmt = $db->prepare("SELECT 1 FROM `bookings` WHERE `id` = ? LIMIT 1");
        $stmt->execute([$id]);
        if (!$stmt->fetch()) Response::notFound('Bookings not found');

        $data   = $req->body;
        $errors = bookings_validate_update($data);
        if ($errors) Response::unprocessable($errors);

        $values   = array_map(fn($c) => $data[$c] ?? null, array (
  0 => 'user_id',
  1 => 'room_id',
  2 => 'check_in',
  3 => 'check_out',
  4 => 'status',
));
        $values[] = $id;
        $stmt     = $db->prepare("UPDATE `bookings` SET `user_id` = ?, `room_id` = ?, `check_in` = ?, `check_out` = ?, `status` = ? WHERE `id` = ?");
        $stmt->execute($values);

        $stmt = $db->prepare("SELECT * FROM `bookings` WHERE `id` = ? LIMIT 1");
        $stmt->execute([$id]);
        Response::ok($stmt->fetch());
    }

    // DELETE /bookings/{id}  — delete
    if ($req->method === 'DELETE' && $id !== null) {
        $stmt = $db->prepare("SELECT 1 FROM `bookings` WHERE `id` = ? LIMIT 1");
        $stmt->execute([$id]);
        if (!$stmt->fetch()) Response::notFound('Bookings not found');

        $stmt = $db->prepare("DELETE FROM `bookings` WHERE `id` = ?");
        $stmt->execute([$id]);
        Response::noContent();
    }

    Response::error('Method not allowed', 405);
}